#!/usr/bin/env python3
import sys

YES = "Yes"  # type: str
NO = "No"  # type: str


def isp(S):
    m = len(S)
    flag = True
    for i in range(m//2):
        if S[i] != S[m-i-1]:
            flag = False
    return flag


def solve(S: str):
    n = len(S)
    if isp(S) and isp(S[:(n-1)//2]) and isp(S[(n+1)//2:]):
        print(YES)
    else:
        print(NO)
    return


# Generated by 1.1.6 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    S = next(tokens)  # type: str
    solve(S)

if __name__ == '__main__':
    main()
